    /// writing to this file, where the one write and its `defer` sit together.
    private(set) var callScope: UInt32?

    /// The document the CURRENT call is pinned to (spec §11 AI-5), or nil for
    /// an MCP call. `targetDocument` checks it first. Written only by
    /// `pinning`, on the lane's thread under its lock, before any main hop.
    private(set) var callDocument: ProjectDocument?

    /// The catalog `prepareCatalog()` built, once it has succeeded. The
    /// assistant's session reads it and never prepares (AI-3).
    private(set) var preparedCatalog: String?

    private init() {}

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("AgentServer does not support NSCoder")
    }

    /// A tool's refusal, reported to the model IN BAND (`isError: true`) so it
    /// can read the message and correct itself rather than seeing a transport
    /// failure. Never surfaced as an alert: a modal on this dispatched-to-main
    /// path would block the main thread — and with it the MCP connection —
    /// until somebody clicked it.
    struct ToolError: Error {
        let message: String
    }

    /// A failure to build the catalog. Logged, never an alert: the socket's
    /// bind reports it in its one log line.
    struct ToolFailure: LocalizedError {
        let message: String
        var errorDescription: String? { message }
    }

    /// The tools whose handler runs on the SERVER thread instead of the main
    /// one, because each WAITS for something the main thread has to deliver or
    /// must not be doing. `import_media` and `relink_media` (spec §11, #63)
    /// wait on a probe whose completion `MediaImporter` posts to the main
    /// thread and `save_project` /
    /// `new_project` on NSDocument's asynchronous save, both of which a
    /// main-thread wait would deadlock against; `render_frame` and `export`
    /// block on decode and encode, and freezing the UI for a whole write is
    /// not acceptable. `transcribe` waits on a recognition task — whose
    /// callbacks the Speech framework delivers on an `OperationQueue` that
    /// defaults to the app's MAIN one — after extracting the clip's audio, so
    /// it is `import_media`'s case twice over. `record_screen` waits on the
    /// recorder, whose every callback is hopped to main, for up to ten
    /// minutes — `import_media`'s case again, and longer. `open_project`
    /// reads the file here, a WebM's copy included, so main is not held for
    /// its length (spec §11 #231). `sync_audio`'s plan is seconds of signal
    /// arithmetic on a long take, which main must not be doing (SY-22). Each
    /// hops back through `onMain` for every
    /// document touch, so the single-mutation-point rule is untouched.
    ///
    /// The criterion is NOT "touches the disk", which is why
    /// `detect_silence`, `consolidate_media`, `import_captions` and
    /// `export_captions` are all absent: each reads or writes a file on the
    /// main thread and each says so in its own handler.
    private static let productOffMainTools: Set<String> = [
        "import_media", "relink_media", "render_frame", "export", "save_project", "new_project",
        "transcribe", "record_screen", "render_graphic", "open_project", "sync_audio",
        "transcribe_for_fillers", "get_transcript", "export_graphic",
    ]
    // The dev tools' members join here (AgentServer+DevTools.swift).
    static let offMainTools = productOffMainTools.union(devOffMainTools)

    // MARK: - Lifecycle

    /// Builds the catalog, fills the gate and runs the parity check, once per
    /// launch (spec §11 AI-3): `AgentLane.prepareAtLaunch()` calls it from
    /// `main.swift`, and `bindSocket()` gets the memoised string. Main only; a
    /// throw is not memoised.
    @discardableResult
    func prepareCatalog() throws -> String {
        assert(Thread.isMainThread)
        if let prepared = preparedCatalog { return prepared }
        let catalog = try catalogJSON()
        // The gate reads this same string at every call (AgentServer+Gate.swift).
        Self.noteArguments(in: catalog)
        // Nothing else forces the catalog and the dispatch table to agree, so
        // debug builds refuse to start the server on a mismatch. `make app`
        // builds Release, where an `assert` is compiled out — which would make
        // the one enforcement of the parity rule dead in every shipped build —
        // so Release logs the same message instead of failing silently.
        if let failure = Self.catalogParityFailure(catalog) {
            assertionFailure(failure)
            NSLog("Frame Job: %@", failure)
        }
        preparedCatalog = catalog
        return catalog
    }

    // MARK: - Dispatch

    /// Executes one tool call and returns CallToolResult JSON. Errors are
    /// in-band (`isError: true`) so the model can read and correct them.
import Foundation

/// The build's catalog snapshot (road map 14's MC3, spec §11 MC-4): with
/// `-RCWriteCatalog <path>`, the launch writes `{"version":…,"tools":…}` —
/// the bundle's `CFBundleShortVersionString` and the catalog
/// `AgentLane.prepareAtLaunch()` just prepared, verbatim — to `<path>` and
/// exits before `NSApplicationMain`, so no window, Dock icon or socket ever
/// appears. `project.yml`'s "Write Agent Catalog" phase runs the just-built
/// binary this way to put `Contents/Resources/agent-catalog.json` in the
/// bundle, which `framejob-mcp` answers `tools/list` from while no Frame Job
/// runs (MC1 q1 measured the phase; `tools/proof/dist_check.py` D21–D24 check
/// the file).
///
/// The key is read from the ARGUMENT domain only, so no persisted default
/// can turn an ordinary launch into a writer. A failure is one stderr line,
/// `framejob catalog snapshot: …`, and exit 1 — never the `Frame Job: `
/// prefix, which is the parity check's (the phase fails on that too).
enum AgentCatalogSnapshot {
    static let argumentKey = "RCWriteCatalog"

    /// Returns when the launch has no `-RCWriteCatalog`; otherwise writes
    /// the snapshot and exits.
    static func writeIfAsked() {
        let arguments = UserDefaults.standard.volatileDomain(forName: UserDefaults.argumentDomain)
        guard let path = arguments[argumentKey] as? String else { return }
        guard let catalog = AgentServer.shared.preparedCatalog else {
            fail("no prepared catalog (the catalog did not build at launch)")
        }
        let version =
            Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? ""
        guard
            let versionJSON = try? JSONSerialization.data(
                withJSONObject: version, options: [.fragmentsAllowed]),
            let versionText = String(data: versionJSON, encoding: .utf8)
        else {
            fail("the version \(version) did not encode as JSON")
        }
        let text = "{\"version\":\(versionText),\"tools\":\(catalog)}"
        do {
            try Data(text.utf8).write(to: URL(fileURLWithPath: path), options: .atomic)
        } catch {
            fail("could not write \(path): \(error.localizedDescription)")
        }
        exit(0)
    }

    private static func fail(_ reason: String) -> Never {
        FileHandle.standardError.write(Data("framejob catalog snapshot: \(reason)\n".utf8))
        exit(1)
    }
}

